(async function(){
'use strict';
const E=NatEngine,S=NatStorage,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let updateLock=false,pendingWrites=0;
let state,profileId,currentMonth=E.month(E.today()),page='dashboard',filter='',kindFilter='',allMonths=false,imported=null,importFile='',toastTimer;
const p=()=>state.profiles.find(x=>x.id===profileId), fmt=E.money, name=(key,id)=>p()[key].find(x=>x.id===id)?.name||'—';
const pretty=m=>new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'}),date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR'):'—';
const expenseClasses={fixed:'Fixa',variable:'Variável',excess:'Excedente'};
const kinds={expense:'Despesa',income:'Receita',card:'Compra no cartão',transfer:'Transferência',refund:'Estorno',reimbursement:'Reembolso'};
const labels=NatNavigation.labels;
const navigation=NatNavigation.create();
function toast(msg,error=false){$('#toast').textContent=msg;$('#toast').className=error?'error':'';clearTimeout(toastTimer);toastTimer=setTimeout(()=>{$('#toast').textContent='';},6500);}
async function mutate(fn){if(updateLock)throw Error('Atualização em andamento. Aguarde a recarga.');pendingWrites++;try{const next=E.clone(state),target=next.profiles.find(x=>x.id===profileId);await fn(target,next);state=await S.save(next);render();}finally{pendingWrites--;}}
function button(label,action,id='',cls=''){return `<button type="button" class="${cls}" data-action="${action}"${id?` data-id="${esc(id)}"`:''}>${label}</button>`;}
function option(value,text,selected){return `<option value="${esc(value)}"${value===selected?' selected':''}>${esc(text)}</option>`;}
function options(key,selected,empty=false){return (empty?option('','Selecione',selected):'')+p()[key].map(x=>option(x.id,x.name,selected)).join('');}
function select(label,n,key,selected,extra=''){return `<label>${label}<select name="${n}" ${extra}>${options(key,selected)}</select></label>`;}
function field(label,n,type='text',value='',extra=''){return `<label>${label}<input name="${n}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function val(n){return (n/100).toFixed(2);}
function empty(title,desc=''){return `<div class="empty"><strong>${esc(title)}</strong>${esc(desc)}</div>`;}
function modal(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#dialog-body input:not([type=checkbox]),#dialog-body select')?.focus(),0);}
function form(id,body,submit='Salvar'){return `<form id="${id}" class="stack"><div id="form-error" class="notice error" role="alert" hidden></div>${body}<div class="dialog-foot">${button('Cancelar','close-modal')}<button class="primary" type="submit">${submit}</button></div></form>`;}
function close(){ $('#modal').close();}
function status(e){if(e.kind==='transfer')return '<span class="pill green">Efetivada</span>';const paid=e.cardId?E.paid(p(),E.invoiceId(e.cardId,e.month)):E.paid(p(),e.id),total=e.cardId?E.invoice(p(),e.cardId,e.month).amount:e.amount;return paid>=total?'<span class="pill green">'+(e.kind==='income'?'Recebida':'Pago')+'</span>':paid?'<span class="pill amber">Parcial</span>':`<span class="pill ${e.date<E.today()?'red':''}">${['income','reimbursement','refund'].includes(e.kind)&&!e.cardId?'A receber':'Pendente'}</span>`;}
function periodInfo(){return p().periods.find(x=>x.month===currentMonth);}
function heading(title,desc,actions=''){return `<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,n,caption,cls=''){return `<div class="metric ${cls}"><span>${label}</span><div class="value">${fmt(n)}</div><small>${caption}</small></div>`;}
function entryRows(rows,actions=true){if(!rows.length)return empty('Nenhum lançamento neste período','Seus registros aparecerão aqui.');return `<div class="table-wrap"><table><thead><tr><th>Descrição / categoria</th><th>Vencimento</th><th>Conta / cartão</th><th class="num">Valor</th><th>Status</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(name('categories',e.categoryId))} · ${kinds[e.kind]}${e.kind==='expense'&&e.expenseClass?' · '+expenseClasses[e.expenseClass]:''}${e.purchaseId||e.importStandalone&&e.number?` · ${e.number}/${e.count}`:''}${e.importStandalone?' · Importado sem cronograma':''}${e.ruleId?' · Recorrente':''}${e.estimated?' · Estimativa':''}</small></td><td>${date(e.date)}<small>${esc(e.month)}</small></td><td>${esc(name(e.cardId?'cards':'accounts',e.cardId||e.accountId))}${e.kind==='transfer'?`<small>Destino: ${esc(name('accounts',e.toAccountId))}</small>`:''}</td><td class="num">${fmt(e.amount)}</td><td>${status(e)}</td>${actions?`<td><div class="actions">${!e.cardId&&e.kind!=='transfer'?button('Baixar','settle-entry',e.id,'small'):''}${!e.purchaseId?button('Editar','edit-entry',e.id,'small'):''}${button('Remover','delete-entry',e.id,'small danger')}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function categoryPanel(rows){const cats=p().categories.map(c=>({...c,total:rows.filter(e=>e.categoryId===c.id).reduce((a,e)=>a+E.consumption(e),0)})).filter(c=>c.total!==0);const max=Math.max(1,...cats.map(c=>Math.abs(c.total)));return cats.length?`<div class="category">${cats.sort((a,b)=>b.total-a.total).map(c=>`<details><summary><div class="category-line"><span>${esc(c.name)}</span><strong>${fmt(c.total)}</strong></div><div class="progress"><i style="width:${Math.max(0,c.total)/max*100}%"></i></div></summary>${rows.filter(e=>e.categoryId===c.id&&E.consumption(e)).map(e=>`<div class="row"><span>${esc(e.description)}<small>${date(e.date)}</small></span><span>${fmt(E.consumption(e))}</span></div>`).join('')}</details>`).join('')}</div>`:empty('Tudo pronto para começar','As despesas por categoria serão calculadas pelos seus lançamentos.');}
function dashboard(){const s=E.stats(p(),currentMonth),b=E.balances(p()),next=E.addMonth(currentMonth),v=E.preview(p(),next,currentMonth),sn=E.stats(p(),next),futureRules=v.candidates.filter(c=>c.type==='rule'),projectedExpense=sn.total+futureRules.filter(c=>c.record.kind==='expense').reduce((a,c)=>a+c.amount,0),projectedIncome=sn.income+futureRules.filter(c=>c.record.kind==='income').reduce((a,c)=>a+c.amount,0);
 const due=s.obligations.filter(x=>x.amount>x.paid).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,6);
 return heading('Seu dinheiro, com clareza',`${esc(p().name)} · ${pretty(currentMonth)}`,button('Novo lançamento','new-entry','','primary')+button('Fechar mês e iniciar próximo mês','close-month'))+
 `<div class="metrics">${metric('Compromissos do mês',s.total,'Despesas diretas + faturas','feature')}${metric('Total pago',s.paid,'Baixas dos compromissos deste mês','good')}${metric('Em aberto',s.open,'Inclui pagamentos parciais')}${metric('Valores vencidos',s.overdue,'Em aberto com vencimento anterior a hoje','warn')}</div>`+
 `<div class="grid"><section class="panel"><div class="panel-title"><h2>Despesas por categoria</h2><span class="pill">Consumo ${fmt(s.consumption)}</span></div>${categoryPanel(s.rows)}<small>Compras são despesas na competência da parcela. Pagar a fatura movimenta o caixa.</small></section><section class="panel"><div class="panel-title"><h2>Próximos vencimentos</h2><span class="pill">${due.length} exibidos</span></div>${due.length?due.map(e=>`<div class="row"><div><strong>${esc(e.cardId?'Fatura · '+name('cards',e.cardId):e.description)}</strong><small>${date(e.date)} ${e.date<E.today()?'· Vencido':''}</small></div><div class="amount">${fmt(e.amount-e.paid)}<small>${button('Baixar',e.cardId?'settle-invoice':'settle-entry',e.id,'small')}</small></div></div>`).join(''):empty('Sem vencimentos em aberto','Neste mês, por enquanto.')}</section></div>`+
 `<div class="grid equal"><section class="panel"><div class="panel-title"><h2>Receitas e contas</h2>${button('Contas','go-settings','','small')}</div><div class="row"><span>Receitas previstas e confirmadas</span><strong>${fmt(s.income)}</strong></div><div class="row"><span>Efetivamente recebidas</span><strong>${fmt(s.received)}</strong></div>${p().accounts.length?p().accounts.map(a=>`<div class="row"><span>${esc(a.name)}<small>Saldo atual · histórico de caixa até hoje</small></span><strong>${fmt(b[a.id])}</strong></div>`).join(''):empty('Cadastre sua primeira conta','Informe o saldo anterior aos movimentos que lançará.')}</section><section class="panel"><div class="panel-title"><h2>Faturas dos cartões</h2>${button('Ver cartões','go-cards','','small')}</div>${invoiceList(s.inv)}</section></div>`+
 `<div class="month-banner"><div><h2>O próximo mês começa organizado</h2><p>${pretty(next)} · ${fmt(projectedExpense)} em compromissos previstos · ${fmt(projectedIncome)} em receitas previstas.</p><small>Inclui registros existentes e recorrências faltantes. Metas conservam seu progresso.</small></div>${button('Conferir continuidade','start-next','','primary')}</div><section class="panel"><div class="panel-title"><h2>Parcelamentos futuros</h2>${button('Relatório completo','go-reports','','small')}</div>${futureInstallments(5)}</section>`;
}
function invoiceList(list){return list.length?list.map(i=>`<div class="row"><div><strong>${esc(name('cards',i.cardId))}</strong><small>Vence ${date(i.date)} · ${i.rows.length} lançamento(s)${i.credit?' · Crédito '+fmt(i.credit):''}</small></div><div class="amount">${fmt(i.amount)}<small>Pago ${fmt(i.paid)}</small>${button('Detalhes','invoice-details',i.id,'small')}${i.amount>i.paid?' '+button('Pagar','settle-invoice',i.id,'small'):''}</div></div>`).join(''):empty('Nenhuma fatura neste mês','Cadastre um cartão e registre suas compras.');}
function futureInstallments(limit=200){const rows=p().entries.filter(e=>e.purchaseId&&e.month>currentMonth).sort((a,b)=>a.date.localeCompare(b.date));return rows.length?entryRows(rows.slice(0,limit),false)+`<small>${rows.length} parcela(s) futura(s) · ${fmt(rows.reduce((a,e)=>a+e.amount,0))}</small>`:empty('Sem parcelas futuras');}
function entries(){let rows=p().entries.filter(e=>(allMonths||e.month===currentMonth)&&(!kindFilter||e.kind===kindFilter)&&`${e.description} ${e.notes||''} ${name('categories',e.categoryId)}`.toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>a.date.localeCompare(b.date));return heading('Lançamentos','Previsões, compromissos e movimentações, em um só lugar.',button('Novo lançamento','new-entry','','primary')+button('Compra no cartão','new-purchase'))+`<section class="panel"><div class="toolbar"><label>Pesquisar<input id="search" type="search" value="${esc(filter)}" placeholder="Descrição, categoria ou observação"></label><label>Tipo<select id="kind-filter">${option('','Todos',kindFilter)}${Object.entries(kinds).map(([k,v])=>option(k,v,kindFilter)).join('')}</select></label><label class="check"><input id="all-months" type="checkbox" ${allMonths?'checked':''}>Todos os meses</label></div>${entryRows(rows)}<div class="spacer muted">${rows.length} registro(s). Baixas podem ser parciais. Remover uma parcela remove toda a compra, se não houver pagamentos.</div></section>`;}
function cards(){return heading('Cartões de crédito','Compras e faturas sem duplicar suas despesas.',button('Nova compra','new-purchase','','primary')+button('Cadastrar cartão','new-card'))+`<div class="card-grid">${p().cards.map(c=>{const i=E.invoice(p(),c.id,currentMonth),out=p().entries.filter(e=>e.cardId===c.id).reduce((a,e)=>a+E.consumption(e),0)-p().settlements.filter(s=>s.sourceType==='invoice'&&s.sourceId.startsWith('invoice:'+c.id+':')).reduce((a,s)=>a+s.amount,0);return `<section class="panel card-tile"><div class="panel-title"><h2>${esc(c.name)}</h2>${button('Editar','edit-card',c.id,'small ghost')}</div><small>Fatura · ${pretty(currentMonth)}</small><div class="card-value spacer">${fmt(i.amount)}</div><small>Fecha dia ${c.closeDay} · vence dia ${c.dueDay}</small><div class="row"><span>Limite ${c.limit?fmt(c.limit):'não informado'}</span><span>Em aberto ${fmt(Math.max(0,out))}</span></div></section>`;}).join('')}</div><section class="panel spacer"><div class="panel-title"><h2>Faturas de ${pretty(currentMonth)}</h2></div>${invoiceList(E.invoices(p(),currentMonth))}</section><div class="notice spacer">Compras feitas no dia do fechamento entram no ciclo seguinte. Se o vencimento for no mesmo dia ou antes do fechamento, a fatura vence no mês posterior ao fechamento. Dias 29–31 são ajustados ao último dia do mês. Confirme as datas com seu banco.</div>`;}
function rules(){return heading('Contas fixas','Despesas e receitas recorrentes. Cada ocorrência pode ser ajustada separadamente.',button('Nova recorrência','new-rule','','primary')+button('Gerar neste mês','complete-month'))+`<section class="panel">${p().rules.length?`<div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Periodicidade</th><th>Previsto</th><th>Situação</th><th>Ações</th></tr></thead><tbody>${p().rules.map(r=>`<tr><td><strong>${esc(r.description)}</strong><small>${kinds[r.kind]} · ${esc(name('categories',r.categoryId))}${r.variable?' · Estimativa variável':''}</small></td><td>A cada ${r.every} mês(es), dia ${r.day}<small>${date(r.start)} até ${r.end?date(r.end):'sem fim'}</small></td><td>${fmt(r.amount)}</td><td><span class="pill ${r.active?'green':''}">${r.active?'Ativa':'Inativa'}</span></td><td>${button('Editar série futura','edit-rule',r.id,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma recorrência cadastrada','Inclua aluguel, assinaturas, salário e outros compromissos periódicos.')}</section><div class="notice spacer">Uma ocorrência alterada em Lançamentos não muda a série. Ao editar a série futura, as ocorrências ainda não pagas a partir da competência escolhida serão recriadas. Ocorrências antigas e meses fechados ficam protegidos.</div>`;}
function planning(){return heading('Orçamentos e metas','Limites por mês e objetivos que continuam com você.',button('Novo orçamento','new-budget','','primary')+button('Nova meta','new-goal'))+`<div class="grid equal"><section class="panel"><div class="panel-title"><h2>Orçamentos · ${pretty(currentMonth)}</h2></div>${p().budgets.filter(b=>b.month===currentMonth).map(b=>{const used=p().entries.filter(e=>e.month===currentMonth&&e.categoryId===b.categoryId).reduce((a,e)=>a+E.consumption(e),0);return `<div class="row"><div style="flex:1"><strong>${esc(name('categories',b.categoryId))}</strong><small>${fmt(used)} de ${fmt(b.amount)} · ${b.carry?'Continuidade ativa':'Só neste mês'}</small><div class="progress"><i class="${used>b.amount?'over':''}" style="width:${Math.min(100,Math.max(0,used)/b.amount*100)}%"></i></div></div>${button('Editar','edit-budget',b.id,'small')}${button('Remover','delete-budget',b.id,'small danger')}</div>`;}).join('')||empty('Sem orçamento para este mês','Defina um limite para cada categoria.')}</section><section class="panel"><div class="panel-title"><h2>Metas acumuladas</h2></div>${p().goals.map(g=>{const total=p().contributions.filter(c=>c.goalId===g.id).reduce((a,c)=>a+c.amount,0);return `<div class="row"><div style="flex:1"><strong>${esc(g.name)}</strong><small>${fmt(total)} de ${fmt(g.target)} · ${g.active?'Ativa':'Inativa'}</small><div class="progress"><i style="width:${Math.min(100,total/g.target*100)}%"></i></div></div><div class="actions">${button('Progresso','goal-progress',g.id,'small')}${button('Editar','edit-goal',g.id,'small')}</div></div>`;}).join('')||empty('Qual é o seu próximo objetivo?','Crie uma reserva ou planeje uma conquista.')}</section></div><div class="notice">O progresso de metas registra valores já reservados: ele não debita a conta automaticamente. Registre uma transferência entre contas quando houver movimentação real. Contribuições permanecem únicas ao iniciar outro mês.</div>`;}
function settlementsTable(){const list=p().settlements.filter(s=>E.month(s.date)===currentMonth).sort((a,b)=>b.date.localeCompare(a.date));return list.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Origem</th><th>Conta</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${list.map(s=>`<tr><td>${date(s.date)}</td><td>${esc(s.sourceType==='invoice'?'Pagamento de fatura · '+s.obligationMonth:p().entries.find(e=>e.id===s.sourceId)?.description)}<small>Competência ${s.obligationMonth}</small></td><td>${esc(name('accounts',s.accountId))}</td><td>${fmt(s.amount)}</td><td>${button('Remover baixa','delete-settlement',s.id,'small danger')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma baixa efetiva neste mês');}
function reports(){const months=Array.from({length:6},(_,i)=>E.addMonth(currentMonth,i-5)),series=months.map(m=>({...E.stats(p(),m),m})),max=Math.max(1,...series.flatMap(s=>[s.total,s.income]));return heading('Relatórios e projeções','Consulte qualquer competência pelo seletor no topo.',button('Imprimir / salvar PDF','print'))+`<div class="grid equal"><section class="panel"><h2>Evolução em seis meses</h2><div class="bars">${series.map(s=>`<div class="bar-group"><div class="bar-pair"><i title="Receitas: ${fmt(s.income)}" style="height:${s.income/max*100}%"></i><i class="exp" title="Compromissos: ${fmt(s.total)}" style="height:${s.total/max*100}%"></i></div><small>${s.m.slice(5)}/${s.m.slice(2,4)}</small></div>`).join('')}</div><div class="legend"><span>Receitas previstas + confirmadas</span><span>Compromissos</span></div></section><section class="panel"><h2>Previsto versus confirmado</h2><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Compromissos</th><th>Pago</th><th>Recebido / previsto</th></tr></thead><tbody>${series.map(s=>`<tr><td>${s.m}</td><td>${fmt(s.total)}</td><td>${fmt(s.paid)}</td><td>${fmt(s.received)} / ${fmt(s.income)}</td></tr>`).join('')}</tbody></table></div></section></div><div class="grid equal"><section class="panel"><h2>Consumo por categoria</h2>${categoryPanel(E.stats(p(),currentMonth).rows)}</section><section class="panel"><h2>Total por cartão</h2>${invoiceList(E.invoices(p(),currentMonth))}</section></div><section class="panel spacer"><h2>Histórico de pagamentos e recebimentos · data de caixa</h2>${settlementsTable()}</section><section class="panel spacer"><h2>Compromissos e projeções dos próximos seis meses</h2><div class="table-wrap"><table><thead><tr><th>Mês</th><th>Despesas e faturas</th><th>Receitas</th><th>Diferença prevista</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>{const m=E.addMonth(currentMonth,i+1),s=E.stats(p(),m),v=E.preview(p(),m,currentMonth),r=v.candidates.filter(x=>x.type==='rule'),out=s.total+r.filter(x=>x.record.kind==='expense').reduce((a,x)=>a+x.amount,0),inc=s.income+r.filter(x=>x.record.kind==='income').reduce((a,x)=>a+x.amount,0);return `<tr><td>${m}</td><td>${fmt(out)}</td><td>${fmt(inc)}</td><td>${fmt(inc-out)}</td></tr>`;}).join('')}</tbody></table></div><small>Projeção usa as regras ativas e os registros já existentes, sem supor novas compras. Diferença não equivale a saldo bancário.</small></section><section class="panel spacer"><h2>Orçamento previsto versus consumo</h2>${p().budgets.filter(x=>x.month===currentMonth).map(b=>`<div class="row"><span>${esc(name('categories',b.categoryId))}</span><span>${fmt(b.amount)} previsto / ${fmt(p().entries.filter(e=>e.month===currentMonth&&e.categoryId===b.categoryId).reduce((a,e)=>a+E.consumption(e),0))} realizado</span></div>`).join('')||empty('Sem orçamento neste mês')}</section><section class="panel spacer"><h2>Parcelamentos futuros</h2>${futureInstallments()}</section>`;}
function monthsPage(){const months=[...new Set([currentMonth,...p().periods.map(x=>x.month),...p().entries.map(x=>x.month)])].sort().reverse();return heading('Meses e fechamentos','Seu histórico permanece consultável, inclusive depois de fechar o mês.',button('Fechar mês e iniciar próximo mês','close-month','','primary')+button('Iniciar mês futuro','choose-month'))+`<section class="panel">${months.map(m=>{const period=p().periods.find(x=>x.month===m),s=E.stats(p(),m);return `<div class="row"><div><strong>${pretty(m)}</strong><small>${fmt(s.total)} em compromissos · ${fmt(s.open)} em aberto ${period?.reopened?'· Reaberto':''}</small></div><div class="actions"><span class="pill ${period?.closed?'':'green'}">${period?.closed?'Encerrado':'Aberto'}</span>${button('Consultar','view-month',m,'small')}${period?.closed?button('Reabrir','reopen-month',m,'small'):''}</div></div>`;}).join('')}</section><section class="panel spacer"><h2>Registro de alterações</h2><div class="audit">${p().audit.slice().reverse().slice(0,100).map(a=>`<div class="row"><span>${esc(a.action)}<small>${esc(a.detail)}</small></span><small>${new Date(a.at).toLocaleString('pt-BR')}</small></div>`).join('')||empty('Nenhuma alteração registrada')}</div><small>Trilha operacional local; não é um mecanismo contra adulteração por quem controla o arquivo ou o navegador.</small></section>`;}
function backups(){return heading('Backup e restauração','Seu histórico pode acompanhar você em um arquivo JSON.')+`<div class="grid equal"><section class="panel"><h2>Salvar Backup</h2><p class="muted">O backup completo preserva todos os meses de ${esc(p().name)}, contas, parcelas e relacionamentos.</p><div class="row"><span>Última exportação</span><strong>${p().lastBackup?new Date(p().lastBackup).toLocaleString('pt-BR'):'Ainda não realizada'}</strong></div><div class="actions spacer">${button('Salvar Backup','export','','primary')}</div><small class="backup-note">Download comum registra a solicitação de exportação. Confira se o arquivo foi salvo pelo navegador.</small></section><section class="panel"><h2>Importar Backup</h2><p class="muted">Confira origem, versão, período e conflitos antes de mesclar ou restaurar.</p><label>Arquivo JSON<input type="file" id="import-file" accept=".json,application/json"></label><p class="muted spacer">Arquivos criptografados exigem a senha usada na exportação.</p></section></div><div class="notice backup-note">No iPhone, o arquivo pode ser salvo em Arquivos ou iCloud Drive pelo mecanismo disponível no navegador. Organize, por exemplo, <strong>iCloud Drive / Nat Finance / ${esc(p().name)}</strong>. A escolha da pasta é sua; arquivos no iCloud não sincronizam automaticamente os dados internos do aplicativo.</div><div class="notice warning">No iPhone, instale pelo Safari usando o endereço HTTPS e Adicionar à Tela de Início. Aguarde a confirmação de uso offline e confira os dados na instalação definitiva. iPhone físico ainda não foi validado. Exporte backups e confira a restauração antes de depender de um navegador.</div>`;}
function settings(){return heading('Configurações','Perfis independentes, contas, cartões e categorias.',button('Novo perfil','new-profile','','primary'))+`<div class="grid equal"><section class="panel"><div class="panel-title"><h2>Contas bancárias</h2>${button('Adicionar','new-account','','small')}</div>${p().accounts.map(a=>`<div class="row"><span><strong>${esc(a.name)}</strong><small>Saldo inicial: ${fmt(a.initial)} · ${a.type==='cash'?'Dinheiro':a.type==='bank'?'Conta bancária':a.type==='other'?'Outra conta':'Tipo não informado'}</small></span><div class="actions">${button('Editar','edit-account',a.id,'small')}${button('Remover','delete-account',a.id,'small danger')}</div></div>`).join('')||empty('Comece cadastrando uma conta','O saldo inicial deve ser anterior aos movimentos registrados.')}</section><section class="panel"><div class="panel-title"><h2>Categorias</h2>${button('Adicionar','new-category','','small')}</div>${p().categories.map(c=>`<div class="row"><span>${esc(c.name)}</span><div class="actions">${button('Editar','edit-category',c.id,'small')}${button('Remover','delete-category',c.id,'small danger')}</div></div>`).join('')}</section></div><section class="panel"><h2>Perfis financeiros</h2>${state.profiles.map(x=>`<div class="row"><strong>${esc(x.name)}</strong><span class="pill">${x.entries.length} lançamentos</span></div>`).join('')}<p class="muted spacer">A separação entre perfis é lógica. Esta versão não possui autenticação nem sincronização em nuvem.</p><h2 class="spacer">Armazenamento neste navegador</h2><p>${S.mode==='indexeddb'?'IndexedDB ativo. Cada alteração é gravada em uma transação com proteção contra gravações desatualizadas de outra janela.':S.mode==='localstorage'?'Modo alternativo localStorage. Use apenas uma janela por vez; exporte backups com frequência.':'Somente memória nesta sessão. Não há persistência local disponível.'}</p><p class="muted">Manter o mesmo HTML, navegador e perfil ajuda a conservar o acesso ao banco. Mover ou renomear o arquivo, limpar os dados do navegador ou usar uma janela privada pode impedir esse acesso. Uma gravação bem sucedida não garante retenção após limpeza do sistema.</p></section>`;}
const expenseUI=NatExpenseImportUI.create({getState:()=>state,getProfileId:()=>profileId,getMonth:()=>currentMonth,mutate,render:()=>render(),toast,modal});
function render(){
 $('#profile-select').innerHTML=state.profiles.map(x=>option(x.id,x.name,profileId)).join('');$('#month-select').value=currentMonth;$('#avatar').textContent=p().name.charAt(0).toUpperCase();navigation.render(page,p(),S.mode);
 const warning=S.mode==='memory'?'<div class="notice error"><strong>Sem armazenamento persistente.</strong> Os dados desta sessão serão perdidos ao fechar. Exporte um backup antes de sair.</div>':S.mode==='localstorage'?'<div class="notice warning">IndexedDB indisponível: usando localStorage. Mantenha apenas uma janela aberta e faça backups frequentes.</div>':'';
 const closed=periodInfo()?.closed?`<div class="notice warning">Esta competência está encerrada. ${button('Reabrir mês','reopen-month',currentMonth,'small')}</div>`:'';
 $('#main').innerHTML=warning+closed+({dashboard,entries,cards,rules,planning,reports,months:monthsPage,backups,imports:()=>expenseUI.render(),settings}[page]());
}
const transactionUI=NatTransactionForm.create({profile:p,month:()=>currentMonth,modal,form});
function entryForm(id){transactionUI.open(id);}
function purchaseForm(){if(!p().cards.length){toast('Cadastre um cartão primeiro.',true);cardForm();return;}modal('Registrar compra no cartão',form('purchase-form',`<div class="form-grid">${field('Descrição','description','text','','required maxlength="160"')}${field('Valor total (R$)','amount','text','','required inputmode="decimal"')}${select('Cartão','cardId','cards')}${select('Categoria','categoryId','categories')}${field('Data da compra','date','date',E.today(),'required')}${field('Número de parcelas','count','number',1,'required min="1" max="120"')}<label class="full">Observações<textarea name="notes" maxlength="2000"></textarea></label></div><div class="notice">O valor total será dividido em centavos exatos. Compras no dia do fechamento entram no ciclo seguinte. O cronograma completo será preservado; trocar de mês não recria parcelas.</div>`,'Criar cronograma'));transactionUI.bindPurchaseForm();}
function accountForm(id){const a=id?E.entity(p(),'accounts',id):{initial:0};modal(id?'Editar conta':'Cadastrar conta',form('account-form',`<input name="id" type="hidden" value="${esc(id||'')}">${field('Nome da conta','name','text',a.name||'','required maxlength="100"')}<label>Tipo de conta<select name="accountType">${option('bank','Conta bancária',a.type||'bank')}${option('cash','Dinheiro / carteira',a.type||'bank')}${option('other','Outra conta',a.type||'bank')}</select></label>${field('Saldo inicial anterior aos lançamentos (R$)','initial','text',val(a.initial),'required inputmode="decimal"')}<small>Para saldo negativo, use sinal de menos. Alterar o saldo inicial afeta todos os saldos históricos.</small>`));}
function cardForm(id){const c=id?E.entity(p(),'cards',id):{closeDay:25,dueDay:5};modal(id?'Editar cartão':'Cadastrar cartão',form('card-form',`<input name="id" type="hidden" value="${esc(id||'')}"><div class="form-grid">${field('Nome (Nubank, Mercado Pago, Itaú…)','name','text',c.name||'','required maxlength="100"')}${field('Limite opcional (R$)','limit','text',c.limit?val(c.limit):'','inputmode="decimal"')}${field('Dia do fechamento','closeDay','number',c.closeDay,'required min="1" max="31"')}${field('Dia do vencimento','dueDay','number',c.dueDay,'required min="1" max="31"')}</div><div class="notice">Alterar as datas do cartão afeta apenas novas compras. As faturas com lançamentos existentes preservam seus vencimentos; mudanças de ciclo exigem novo cartão.</div>`));}
function ruleForm(id){if(!p().accounts.length){toast('Cadastre uma conta primeiro.',true);page='settings';render();return;}const r=id?E.entity(p(),'rules',id):{kind:'expense',day:5,every:1,start:currentMonth+'-01',active:true};modal(id?'Editar série futura':'Nova recorrência',form('rule-form',`<input name="id" type="hidden" value="${esc(id||'')}"><div class="form-grid">${field('Descrição','description','text',r.description||'','required maxlength="160"')}<label>Tipo<select name="kind">${option('expense','Despesa',r.kind)}${option('income','Receita',r.kind)}</select></label>${field('Valor previsto (R$)','amount','text',r.amount?val(r.amount):'','required inputmode="decimal"')}${select('Categoria','categoryId','categories',r.categoryId)}${select('Conta','accountId','accounts',r.accountId)}${field('Dia de vencimento / recebimento','day','number',r.day,'required min="1" max="31"')}<label>Periodicidade<select name="every">${[1,3,6,12].map(n=>option(String(n),`A cada ${n} mês(es)`,String(r.every))).join('')}</select></label>${field('Data de início','start','date',r.start,'required')}${field('Data final (opcional)','end','date',r.end||'')}${id?field('Aplicar à série a partir de','from','month',currentMonth,'required'):''}<label class="check"><input type="checkbox" name="variable" ${r.variable?'checked':''}>Valor variável (estimativa)</label><label class="check"><input type="checkbox" name="active" ${r.active?'checked':''}>Regra ativa</label></div><div class="notice">${id?'Ocorrências a partir do mês escolhido serão recriadas com esta regra. Meses fechados e ocorrências pagas bloqueiam essa alteração.':'Após salvar, use “Gerar neste mês” ou inicie uma competência para criar as ocorrências.'}</div>`));}
function budgetForm(id){const b=id?E.entity(p(),'budgets',id):{month:currentMonth,carry:true};modal('Orçamento mensal',form('budget-form',`<input type="hidden" name="id" value="${esc(id||'')}">${select('Categoria','categoryId','categories',b.categoryId)}${field('Limite mensal (R$)','amount','text',b.amount?val(b.amount):'','required inputmode="decimal"')}${field('Competência','month','month',b.month,'required')}<label class="check"><input type="checkbox" name="carry" ${b.carry?'checked':''}>Sugerir transporte para o próximo mês</label>`));}
function goalForm(id){const g=id?E.entity(p(),'goals',id):{active:true};modal('Meta financeira',form('goal-form',`<input type="hidden" name="id" value="${esc(id||'')}">${field('Nome da meta','name','text',g.name||'','required maxlength="100"')}${field('Objetivo (R$)','target','text',g.target?val(g.target):'','required inputmode="decimal"')}<label class="check"><input type="checkbox" name="active" ${g.active?'checked':''}>Meta ativa</label>`));}
function goalProgress(id){const g=E.entity(p(),'goals',id);modal('Progresso · '+g.name,form('contribution-form',`<input type="hidden" name="goalId" value="${esc(id)}">${field('Valor reservado (R$)','amount','text','','required inputmode="decimal"')}${field('Data','date','date',E.today(),'required')}<div>${p().contributions.filter(c=>c.goalId===id).map(c=>`<div class="row"><span>${date(c.date)} · ${fmt(c.amount)}</span>${button('Remover','delete-contribution',c.id,'small danger')}</div>`).join('')}</div><small>Registro de progresso; não gera movimentação bancária.</small>`,'Registrar progresso'));}
function settleForm(id,type){if(!p().accounts.length){toast('Cadastre uma conta primeiro.',true);return;}let e;if(type==='invoice'){e=findInvoice(id);E.assert(e,'Fatura não encontrada.');}else e=E.entity(p(),'entries',id);const remaining=e.amount-E.paid(p(),id);if(remaining<=0){toast('O valor já foi integralmente baixado.');return;}modal(type==='invoice'?'Pagar fatura':'Registrar pagamento / recebimento',form('settlement-form',`<input type="hidden" name="sourceId" value="${esc(id)}"><input type="hidden" name="sourceType" value="${type}"><div class="notice">${esc(type==='invoice'?'Fatura '+name('cards',e.cardId)+' · '+e.month:e.description)}<br>Em aberto: <strong>${fmt(remaining)}</strong></div>${select('Conta movimentada','accountId','accounts',e.accountId)}${field('Valor efetivo (R$)','amount','text',val(remaining),'required inputmode="decimal"')}${field('Data efetiva','date','date',E.today(),`required max="${E.today()}"`)}<small>A baixa movimenta a conta e não cria outra despesa. Pagamentos parciais são permitidos.</small>`,'Confirmar baixa'));}
function findInvoice(id){for(const c of p().cards){const m=id.slice(-7);if(id===E.invoiceId(c.id,m))return E.invoice(p(),c.id,m);}return null;}
function monthPreview(target,closing=false){const from=currentMonth,v=E.preview(p(),target,from),s=E.stats(p(),from);modal(closing?'Fechar mês e iniciar próximo mês':'Iniciar / completar competência',form('month-form',`<input type="hidden" name="target" value="${target}"><input type="hidden" name="from" value="${from}"><input type="hidden" name="closing" value="${closing?'yes':'no'}"><div class="notice"><strong>${esc(p().name)} · ${pretty(target)}</strong><br>${v.exists?'Competência já iniciada: apenas itens ausentes serão incluídos.':'Uma nova competência será criada.'}${v.closed?'<br>O mês de destino está encerrado. Reabra antes de completar.':''}</div>${closing?`<h3>Conferência de ${pretty(from)}</h3><div class="row"><span>Despesas de consumo</span><strong>${fmt(s.consumption)}</strong></div><div class="row"><span>Compromissos / pago / em aberto</span><span>${fmt(s.total)} / ${fmt(s.paid)} / ${fmt(s.open)}</span></div><div class="row"><span>Receitas previstas / recebidas</span><span>${fmt(s.income)} / ${fmt(s.received)}</span></div><div class="row"><span>Faturas / parcelas / vencidos</span><span>${s.inv.length} / ${s.rows.filter(e=>e.purchaseId).length} / ${fmt(s.overdue)}</span></div><small>Obrigações abertas permanecem no mês original. Não é necessário quitá-las para fechar.</small>`:''}<h3>Selecione o que transportar</h3>${v.candidates.length?v.candidates.map(c=>`<label class="check"><input type="checkbox" name="selected" value="${esc(c.key)}" checked><span>${esc(c.label)} · ${fmt(c.amount)}<small> · ${c.type==='budget'?'Orçamento':c.record.kind==='income'?'A receber':'Pendente'}${c.record.estimated?' · Estimativa':''}</small></span></label>`).join(''):empty('Nenhum item ausente para gerar','A competência ainda pode ser iniciada ou consultada.')}<h3>Cronogramas e metas preservados</h3><p>${v.installments.length} parcela(s) já vinculada(s) a ${pretty(target)}: ${fmt(v.installments.reduce((a,e)=>a+e.amount,0))}. Não serão recriadas.</p><p>${v.goals.length} meta(s) ativa(s), com progresso acumulado preservado.</p><small>Parcelas existentes são obrigações da compra original. Para cancelá-las, remova a compra sem baixas vinculadas. Metas ativas continuam no cadastro; use Editar meta para encerrá-las.</small><label class="check"><input type="checkbox" name="confirmed" required>Conferi a prévia e confirmo a operação.</label>`,closing?'Fechar e iniciar próximo mês':'Iniciar / completar mês'));}
function exportForm(){const m=currentMonth,n=p().name;modal('Salvar Backup',form('export-form',`<div class="form-grid"><label>Perfil<input readonly value="${esc(n)}"></label>${field('Mês e ano de referência','reference','month',m,'required')}${field('Nome personalizado','custom','text',`${n} ${new Date(m+'-15').toLocaleDateString('pt-BR',{month:'long'})}`,'required maxlength="120"')}<label>Tipo de backup<select name="type"><option value="full">Completo · todo o histórico</option><option value="monthly">Mensal · período + vínculos necessários</option></select></label><label class="full">Nome sugerido do arquivo<input name="filename" value="${esc(filename(n,m))}" required maxlength="160"></label><label class="full">Senha opcional para criptografar<input name="password" type="password" autocomplete="new-password" minlength="8" placeholder="Deixe vazio para JSON sem senha"></label></div><div class="notice">O completo contém todos os meses deste perfil. O mensal inclui cronogramas completos vinculados ao período para manter a integridade, mas não restaura sozinho todo o histórico. A senha não será salva; sem ela, não há recuperação.</div>`,'Exportar arquivo'));}
function filename(n,m){const title=new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long'});return `${n}_${title.charAt(0).toUpperCase()+title.slice(1)}_${m.slice(0,4)}.json`.replace(/[<>:"/\\|?*]/g,'_').replace(/\s+/g,'_');}
async function keyFrom(password,salt,usage){E.assert(crypto?.subtle,'Criptografia indisponível neste navegador/contexto. Use outro navegador compatível.');const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,[usage]);}
const b64=a=>btoa(Array.from(new Uint8Array(a),b=>String.fromCharCode(b)).join('')),unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function encrypt(b,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await keyFrom(password,salt,'encrypt'),data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(b)));return {app:'Nat Finance',encrypted:true,encryptionVersion:1,algorithm:'AES-256-GCM',kdf:'PBKDF2-SHA256',iterations:310000,salt:b64(salt),iv:b64(iv),data:b64(data)};}
async function decrypt(b,password){E.assert(b.app==='Nat Finance'&&b.encryptionVersion===1&&b.algorithm==='AES-256-GCM'&&b.kdf==='PBKDF2-SHA256'&&b.iterations===310000,'Formato criptografado incompatível.');try{const salt=unb64(b.salt),iv=unb64(b.iv);E.assert(salt.length===16&&iv.length===12,'Parâmetros inválidos.');const key=await keyFrom(password,salt,'decrypt'),raw=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,unb64(b.data));return JSON.parse(new TextDecoder().decode(raw));}catch{throw Error('Senha incorreta, arquivo danificado ou criptografia indisponível.');}}
async function saveFile(data,n){const text=JSON.stringify(data,null,2);if(window.showSaveFilePicker){try{const handle=await window.showSaveFilePicker({suggestedName:n,types:[{description:'Backup Nat Finance JSON',accept:{'application/json':['.json']}}]});const stream=await handle.createWritable();await stream.write(text);await stream.close();return 'saved';}catch(e){if(e.name==='AbortError')return 'cancelled';if(e.name!=='SecurityError'&&e.name!=='NotAllowedError')throw e;}}
 const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=n;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);return 'requested';}
async function readImport(file){E.assert(file.size<=25*1024*1024,'O limite de importação é 25 MB.');importFile=file.name;const raw=JSON.parse(await file.text());if(raw.encrypted){imported=raw;modal('Desbloquear backup',form('decrypt-form',field('Senha do backup','password','password','','required autocomplete="current-password"'),'Desbloquear'));}else{imported=E.parseBackup(raw);importPreview();}}
function importPreview(){const b=imported,src=b.profile,dest=state.profiles.find(x=>x.id===src.id),v=dest?E.mergePreview(dest,b):null,older=dest&&new Date(b.exportedAt)<new Date(dest.updatedAt);modal('Conferir importação',form('import-form',`<div class="notice"><strong>${esc(importFile)}</strong><br>Origem: ${esc(src.name)}<br>Exportado em ${new Date(b.exportedAt).toLocaleString('pt-BR')}<br>Referência: ${pretty(b.reference)} · ${b.type==='full'?'Completo':'Mensal'}<br>Formato ${b.formatVersion} · Compatível<br>${E.collections.map(k=>src[k].length).reduce((a,n)=>a+n,0)} registros, incluindo ${src.entries.length} lançamentos.</div>${older?'<div class="notice warning">Este arquivo é anterior à última alteração do perfil local. Restaurar pode descartar dados mais recentes.</div>':''}${dest?`<p>Destino: <strong>${esc(dest.name)}</strong>${dest.id!==profileId?' (outro perfil; o perfil atual não será substituído)':''}.</p><p>${v.missing.length} registro(s) ausente(s) · ${v.conflicts.length} conflito(s).</p>${v.conflicts.length?`<details><summary>Conferir conflitos · restauração completa necessária para substituir</summary>${v.conflicts.slice(0,50).map(c=>`<p><small>${esc(c.collection)} · ${esc(c.id)}</small></p>`).join('')}</details>`:''}<label>Modo<select name="mode"><option value="merge" ${v.conflicts.length?'disabled':''}>Mesclar registros ausentes, sem sobrescrever</option>${b.type==='full'?`<option value="restore" ${v.conflicts.length?'selected':''}>Restaurar backup completo · substituir ${esc(dest.name)}</option>`:''}</select></label>${b.type==='full'?'<label class="check"><input name="preventive" type="checkbox" checked>Exportar backup preventivo antes de restaurar</label>':''}`:`<p>O perfil original não existe neste navegador. A importação criará um perfil separado: <strong>${esc(src.name)}</strong>.</p><input type="hidden" name="mode" value="new">${b.type==='monthly'?'<div class="notice warning">Este backup mensal é parcial. Saldos iniciais de contas não representam o histórico completo de caixa.</div>':''}`}<label class="check"><input type="checkbox" name="confirmed" required>Conferi o perfil e autorizo ${dest?'a mesclagem ou substituição selecionada':'a criação do perfil separado'}.</label>`,'Confirmar importação'));}
async function confirmDelete(action,id){let msg='Este registro será removido. Exporte um backup antes de continuar.';if(action==='delete-entry'){const e=E.entity(p(),'entries',id);msg=e.purchaseId?'Toda a compra e suas parcelas serão removidas. A operação é bloqueada se existir qualquer pagamento ou mês fechado. Exporte um backup antes de continuar.':`Remover “${e.description}”? Para recorrências, a ocorrência poderá ser gerada novamente ao completar o mês. Exporte um backup antes de continuar.`;}if(!confirm(msg))return;
 await mutate(q=>{if(action==='delete-entry')E.removeEntry(q,id);else if(action==='delete-settlement')E.removeSettlement(q,id);else if(action==='delete-budget'){const b=E.entity(q,'budgets',id);E.ensureOpen(q,b.month);q.budgets=q.budgets.filter(x=>x.id!==id);E.touch(q,'Remover orçamento',id);}else if(action==='delete-contribution'){const c=E.entity(q,'contributions',id);E.ensureOpen(q,E.month(c.date));q.contributions=q.contributions.filter(x=>x.id!==id);E.touch(q,'Remover progresso',id);}else if(action==='delete-account'){E.assert(!q.entries.some(e=>e.accountId===id||e.toAccountId===id)&&!q.settlements.some(s=>s.accountId===id)&&!q.rules.some(r=>r.accountId===id),'Conta possui vínculos e não pode ser removida.');q.accounts=q.accounts.filter(x=>x.id!==id);E.touch(q,'Remover conta',id);}else if(action==='delete-category'){E.assert(!q.entries.some(e=>e.categoryId===id)&&!q.rules.some(r=>r.categoryId===id)&&!q.budgets.some(b=>b.categoryId===id)&&!q.importRules.some(r=>r.categoryId===id),'Categoria possui vínculos.');q.categories=q.categories.filter(x=>x.id!==id);E.touch(q,'Remover categoria',id);}});close();toast('Registro removido.');}
document.addEventListener('click',async event=>{const el=event.target.closest('button');if(!el)return;if(el.type==='submit'&&el.closest('form')&&!el.dataset.action)return;const a=el.dataset.action,id=el.dataset.id;try{if(el.dataset.page){page=el.dataset.page;filter='';navigation.closeMobile();render();return;}if(a?.startsWith('go-')){page=a.slice(3);render();return;}if(a?.startsWith('delete-')){await confirmDelete(a,id);return;}switch(a){
 case 'menu':navigation.toggleMobile();break;case 'close-modal':close();break;
 case 'new-entry':entryForm();break;case 'edit-entry':entryForm(id);break;case 'new-purchase':purchaseForm();break;
 case 'new-account':accountForm();break;case 'edit-account':accountForm(id);break;case 'new-card':cardForm();break;case 'edit-card':cardForm(id);break;
 case 'new-rule':ruleForm();break;case 'edit-rule':ruleForm(id);break;case 'new-budget':budgetForm();break;case 'edit-budget':budgetForm(id);break;case 'new-goal':goalForm();break;case 'edit-goal':goalForm(id);break;case 'goal-progress':goalProgress(id);break;
 case 'new-profile':modal('Criar perfil independente',form('profile-form',field('Nome do perfil','name','text','','required maxlength="100"')));break;
 case 'new-category':case 'edit-category':modal('Categoria',form('category-form',`<input type="hidden" name="id" value="${esc(id||'')}">`+field('Nome','name','text',id?name('categories',id):'','required maxlength="100"')));break;
 case 'settle-entry':settleForm(id,'entry');break;case 'settle-invoice':settleForm(id,'invoice');break;
 case 'invoice-details':{const i=findInvoice(id);modal('Fatura · '+name('cards',i.cardId),`<p>Competência ${i.month} · vence ${date(i.date)}</p><p>Total ${fmt(i.amount)} · pago ${fmt(i.paid)}${i.credit?' · Crédito '+fmt(i.credit):''}</p>${entryRows(i.rows,false)}<p class="muted spacer">Créditos de fatura são abatidos dos próximos ciclos. Não são entradas na conta bancária.</p>`);break;}
 case 'start-next':monthPreview(E.addMonth(currentMonth));break;case 'close-month':monthPreview(E.addMonth(currentMonth),true);break;case 'complete-month':monthPreview(currentMonth);break;
 case 'choose-month':modal('Iniciar mês sem fechar o atual',form('choose-month-form',field('Competência de destino','target','month',E.addMonth(currentMonth),'required'),'Conferir prévia'));break;
 case 'view-month':currentMonth=id;page='dashboard';render();break;
 case 'reopen-month':if(confirm(`Reabrir ${pretty(id)}? As próximas alterações ficarão na trilha de auditoria.`)){await mutate(q=>E.reopen(q,id));toast('Mês reaberto.');}break;
 case 'export':exportForm();break;case 'print':window.print();break;
 }}catch(error){toast(error.message,true);}});
document.addEventListener('change',async e=>{try{if(e.target.id==='profile-select'){profileId=e.target.value;filter='';render();}if(e.target.id==='month-select'){E.assert(E.addMonth(e.target.value,0)===e.target.value,'Competência inválida.');currentMonth=e.target.value;render();}if(e.target.id==='kind-filter'){kindFilter=e.target.value;render();}if(e.target.id==='all-months'){allMonths=e.target.checked;render();}if(e.target.id==='import-file'&&e.target.files[0])await readImport(e.target.files[0]);if(e.target.closest('#export-form')&&['reference','custom'].includes(e.target.name)){const f=e.target.form,m=f.elements.reference.value;if(e.target.name==='reference')f.elements.custom.value=p().name+' '+new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long'});f.elements.filename.value=(f.elements.custom.value+'_'+m.slice(0,4)+'.json').replace(/[<>:"/\\|?*]/g,'_').replace(/\s+/g,'_');}}catch(error){toast(error.message,true);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;filter=e.target.value;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('submit',async event=>{if(event.target.dataset.importUi)return;event.preventDefault();const f=event.target,d=new FormData(f),get=n=>String(d.get(n)||''),id=get('id'),submit=f.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{
 switch(f.getAttribute('id')){
 case 'entry-form':await mutate(q=>E.recordTransaction(q,transactionUI.values(f)));break;
 case 'purchase-form':await mutate(q=>E.purchase(q,{description:get('description').trim(),amount:E.cents(get('amount')),cardId:get('cardId'),categoryId:get('categoryId'),date:get('date'),count:Number(get('count')),firstMonth:get('firstMonth')||undefined,notes:get('notes')}));break;
 case 'account-form':await mutate(q=>{const raw=get('initial'),initial=raw.startsWith('-')?-E.cents(raw.slice(1)):E.cents(raw);if(id){E.assert(!q.periods.some(x=>x.closed),'Reabra as competências antes de alterar uma conta existente.');Object.assign(E.entity(q,'accounts',id),{name:get('name').trim(),initial,type:get('accountType')||'bank'});}else q.accounts.push({id:E.uid(),name:get('name').trim(),initial,type:get('accountType')||'bank'});E.assert(get('name').trim(),'Nome obrigatório.');E.touch(q,'Salvar conta',id);});break;
 case 'card-form':await mutate(q=>{const c={id:id||E.uid(),name:get('name').trim(),limit:get('limit')?E.cents(get('limit')):0,closeDay:Number(get('closeDay')),dueDay:Number(get('dueDay'))};E.assert(c.name,'Nome obrigatório.');if(id){const old=E.entity(q,'cards',id);E.assert(!q.entries.some(e=>e.cardId===id)||(old.closeDay===c.closeDay&&old.dueDay===c.dueDay),'Este cartão tem histórico. Para mudar o ciclo, cadastre outro cartão; o cronograma existente deve ser preservado.');Object.assign(old,c);}else q.cards.push(c);E.touch(q,'Salvar cartão',c.id);});break;
 case 'category-form':await mutate(q=>{E.assert(get('name').trim(),'Nome obrigatório.');E.assert(!q.categories.some(c=>c.id!==id&&c.name.toLowerCase()===get('name').trim().toLowerCase()),'Categoria já existe.');if(id){E.assert(!q.periods.some(x=>x.closed),'Reabra as competências antes de renomear uma categoria.');E.entity(q,'categories',id).name=get('name').trim();}else q.categories.push({id:E.uid(),name:get('name').trim()});E.touch(q,'Salvar categoria',id);});break;
 case 'profile-form':{let createdId;await mutate((q,next)=>{E.assert(get('name').trim(),'Nome obrigatório.');E.assert(!next.profiles.some(x=>x.name.toLowerCase()===get('name').trim().toLowerCase()),'Nome já existe.');const n=E.profile(get('name').trim());next.profiles.push(n);createdId=n.id;});profileId=createdId;render();break;}
 case 'rule-form':await mutate(q=>E.saveRule(q,{id:id||undefined,kind:get('kind'),description:get('description').trim(),amount:E.cents(get('amount')),categoryId:get('categoryId'),accountId:get('accountId'),day:Number(get('day')),every:Number(get('every')),start:get('start'),end:get('end')||null,active:d.has('active'),variable:d.has('variable')},get('from')));break;
 case 'budget-form':await mutate(q=>{const m=get('month'),categoryId=get('categoryId');E.ensureOpen(q,m);if(id)E.ensureOpen(q,E.entity(q,'budgets',id).month);E.assert(!q.budgets.some(x=>x.id!==id&&x.month===m&&x.categoryId===categoryId),'Já existe orçamento para esta categoria e mês.');const r={id:`budget:${categoryId}:${m}`,month:m,categoryId,amount:E.cents(get('amount')),carry:d.has('carry')};if(id)Object.assign(E.entity(q,'budgets',id),r);else q.budgets.push(r);E.ensurePeriod(q,m);E.touch(q,'Salvar orçamento',m);});break;
 case 'goal-form':await mutate(q=>{const g={id:id||E.uid(),name:get('name').trim(),target:E.cents(get('target')),active:d.has('active')};E.assert(g.name,'Nome obrigatório.');if(id)Object.assign(E.entity(q,'goals',id),g);else q.goals.push(g);E.touch(q,'Salvar meta',g.id);});break;
 case 'contribution-form':await mutate(q=>{E.assert(E.validDate?E.validDate(get('date')):/^\d{4}-\d{2}-\d{2}$/.test(get('date')),'Data inválida.');E.assert(get('date')<=E.today(),'Informe uma data efetiva até hoje.');E.ensureOpen(q,E.month(get('date')));q.contributions.push({id:E.uid(),goalId:get('goalId'),date:get('date'),amount:E.cents(get('amount'))});E.touch(q,'Registrar progresso',get('goalId'));});break;
 case 'settlement-form':await mutate(q=>E.settle(q,{sourceId:get('sourceId'),sourceType:get('sourceType'),accountId:get('accountId'),date:get('date'),amount:E.cents(get('amount'))}));break;
 case 'choose-month-form':monthPreview(get('target'));return;
 case 'month-form':{E.assert(d.has('confirmed'),'Confirme a conferência.');await mutate(q=>E.openMonth(q,get('target'),{from:get('from'),selected:d.getAll('selected'),close:get('closing')==='yes'}));currentMonth=get('target');page='dashboard';render();exportForm();toast('Competência preparada. O backup é independente: cancelar não desfaz o mês.');return;}
 case 'export-form':{const m=get('reference'),file=get('filename').trim();E.assert(file&&!/[<>:"/\\|?*\x00-\x1f]/.test(file),'Nome de arquivo inválido.');let b=E.backup(p(),m,get('type'));if(get('password')){E.assert(get('password').length>=8,'Use ao menos 8 caracteres.');b=await encrypt(b,get('password'));}const result=await saveFile(b,file.toLowerCase().endsWith('.json')?file:file+'.json');if(result==='cancelled'){toast('Exportação cancelada. Os dados continuam no aplicativo.');return;}await mutate(q=>{q.lastBackup=E.now();});close();toast(result==='saved'?'Backup gravado no destino escolhido.':'Download solicitado. Confira se o arquivo foi salvo.');return;}
 case 'decrypt-form':imported=E.parseBackup(await decrypt(imported,get('password')));importPreview();return;
 case 'import-form':{E.assert(d.has('confirmed'),'Confirme o destino.');const b=imported,mode=get('mode'),dest=state.profiles.find(x=>x.id===b.profile.id);if(mode==='restore'){E.assert(dest&&b.type==='full','Restauração inválida.');E.assert(confirm(`Substituir TODO o histórico de ${dest.name} pelo backup? Dados locais ausentes no arquivo serão removidos.`),'Restauração cancelada.');if(d.has('preventive')){const result=await saveFile(E.backup(dest,currentMonth),`Preventivo_${filename(dest.name,currentMonth)}`);E.assert(result!=='cancelled','Backup preventivo cancelado; restauração não executada.');E.assert(result==='saved'||confirm('Confira o download do backup preventivo. O arquivo foi salvo e você deseja continuar?'),'Restauração cancelada.');}}await mutate((q,next)=>{if(dest)E.importBackup(next.profiles.find(x=>x.id===dest.id),b,mode);else{const copy=E.clone(b.profile);if(next.profiles.some(x=>x.name.toLowerCase()===copy.name.toLowerCase()))copy.name+=' (importado)';E.touch(copy,'Importar perfil separado',b.exportedAt);next.profiles.push(copy);}});profileId=b.profile.id;currentMonth=b.reference;render();imported=null;break;}
 }
 close();toast('Dados salvos.');
 }catch(error){const box=f.querySelector('#form-error');if(box){box.hidden=false;box.textContent=error.message;box.scrollIntoView({block:'nearest'});}else toast(error.message,true);}finally{if(submit)submit.disabled=false;}});
window.addEventListener('beforeunload',e=>{if(S.mode==='memory'&&state?.profiles.some(x=>x.entries.length)){e.preventDefault();e.returnValue='';}});
window.NatApp={isUpdateSafe:()=>!!state&&pendingWrites===0&&!updateLock&&!document.querySelector('dialog[open]')&&!expenseUI.getUpdateState().busy&&!expenseUI.getUpdateState().draft,setUpdateLock:value=>{updateLock=!!value;}};
try{state=await S.init();profileId=state.profiles[0].id;render();}catch(error){$('#main').innerHTML=`<div class="notice error"><h1>Não foi possível abrir os dados</h1><p>${esc(error.message)}</p><p>Os dados existentes não foram sobrescritos. Preserve os backups e use o mesmo navegador e perfil.</p></div>`;}
})();
